for(const name of ['Georgy Zhukov','David Ricardo','Kazimir Malevich','Sergei Prokofiev'])LEGENDARY_FIGURES.add(name);
const RARITY_WEIGHTS = [.45,.27,.15,.08,.04,.01];
for(const card of CARDS){if(ARCHIVE_FOILS.has(card.name))card.rarity='Archive Foil';else if(LEGENDARY_FIGURES.has(card.name))card.rarity='Legendary';else if(card.rarity==='Archive foil')card.rarity='Epic';else if(card.number%11===0)card.rarity='Epic';}
